namespace {

char g_ctx[256] = "";
void ctx(const char* fmt, ...) {
  va_list ap;
  va_start(ap, fmt);
  std::vsnprintf(g_ctx, sizeof g_ctx, fmt, ap);
  va_end(ap);
}

dance::StageRect rect(int x0, int y0, int x1, int y1) {
  dance::StageRect r;
  r.x0 = static_cast<int16_t>(x0);
  r.y0 = static_cast<int16_t>(y0);
  r.x1 = static_cast<int16_t>(x1);
  r.y1 = static_cast<int16_t>(y1);
  return r;
}
bool sameRect(const dance::StageRect& a, const dance::StageRect& b) {
  return a.x0 == b.x0 && a.y0 == b.y0 && a.x1 == b.x1 && a.y1 == b.y1;
}

// The median's scratch: exactly kBudgetMaxFrames values on the heap.
struct Scratch {
  std::unique_ptr<uint32_t[]> v{new uint32_t[dance::kBudgetMaxFrames]};
  uint32_t* get() { return v.get(); }
};

std::string reasonText(const dance::Reason& r) {
  char buf[dance::kReasonChars];
  dance::formatReason(r, buf, sizeof buf);
  return buf;
}

dance::BudgetCaseSpec spec(int fps, int pace, bool mirrored, int spot) {
  dance::BudgetCaseSpec s;
  s.fps = static_cast<uint8_t>(fps);
  s.pace = static_cast<uint8_t>(pace);
  s.mirrored = mirrored;
  s.spot = static_cast<int8_t>(spot);
  return s;
}

// The fixture with a patch applied to a copy (the CRC recomputed).
Bytes patchedFixture(void (*edit)(Bytes&)) {
  Bytes t = packedit::testPack();
  edit(t);
  packedit::fixCrc(t);
  return t;
}
uint32_t recordAt(const Bytes& t, int move) { return packedit::entry(t, "MOVS").off + 4 + 32 * move; }
uint32_t stepAt(const Bytes& t, int move, int k) {
  return packedit::entry(t, "STEP").off + 8 * (packedit::get16(t, recordAt(t, move) + 24) + k);
}

void clearHeavy(Bytes& t) { t[recordAt(t, beatscript::kHeavy) + 8] &= static_cast<uint8_t>(~dance::kHeavy); }
// big keyed -12,0 and 12,0, as heavy is.
void bigLikeHeavy(Bytes& t) {
  t[stepAt(t, beatscript::kBig, 0) + 4] = static_cast<uint8_t>(-12);
  t[stepAt(t, beatscript::kBig, 1) + 4] = 12;
}
void twoRed(Bytes& t) {
  clearHeavy(t);
  bigLikeHeavy(t);
}
// test_dancepack.py's case: walk without its mirror flag, start_at centre,
// every step's dx 10 (extents (-24, 68) and (-64, 28): no start spot
// unmirrored, spot 0 mirrored only).
void walkFromNoSpot(Bytes& t) {
  const uint32_t rec = recordAt(t, beatscript::kWalk);
  t[rec + 8] &= static_cast<uint8_t>(~dance::kMirror);
  t[rec + 12] = 1;
  for (int k = 0; k < t[rec + 23]; ++k) t[stepAt(t, beatscript::kWalk, k) + 4] = 10;
}

}  // namespace

